import json

with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# Search for any mention of exchange rates or yen in the JSON
def search_json(obj, search_term, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if search_term.lower() in str(k).lower():
                results.append((f'{path}.{k}', str(v)[:200]))
            results.extend(search_json(v, search_term, f'{path}.{k}'))
    elif isinstance(obj, list) and len(obj) > 0:
        results.extend(search_json(obj[0], search_term, f'{path}[0]'))
    return results

# Search for various terms
for term in ['exchange', 'yen', 'jpy', 'march 2004']:
    print(f"\nSearching for '{term}':")
    results = search_json(data, term)
    for r in results[:10]:
        print(f"  {r}")
