import json

# Let me search for any 2004 data in the JSON
with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

def search_for_year(obj, year=2004, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if str(year) in str(k):
                results.append(f'{path}.{k}')
            results.extend(search_for_year(v, year, f'{path}.{k}'))
    elif isinstance(obj, list) and len(obj) > 0:
        results.extend(search_for_year(obj[0], year, f'{path}[0]'))
    return results

results = search_for_year(data, 2004)
print(f"Found {len(results)} mentions of 2004")
for r in results[:30]:
    print(r)
